using System.ComponentModel;

namespace PoeBuilder.App.Services;

/// <summary>Application UI only. This is NOT a translation of PoE's game data.</summary>
public sealed class Localization : INotifyPropertyChanged
{
    private string _language = "ru";
    public string Language => _language;
    public event PropertyChangedEventHandler? PropertyChanged;
    public string this[string key] => Strings.TryGetValue(key, out var pair) ? (_language == "ru" ? pair.Ru : pair.En) : key;
    public void SetLanguage(string language)
    {
        if (language is not ("ru" or "en")) throw new ArgumentException("Unsupported UI language.");
        _language = language;
        PropertyChanged?.Invoke(this, new("Item[]"));
        PropertyChanged?.Invoke(this, new(nameof(Language)));
    }
    public string Format(string key, params object[] args) => string.Format(this[key], args);

